from abc import ABC, abstractmethod

# ❌ OLD: Nominal inheritance. Third-party classes from external libraries
# cannot be passed to draw() unless they explicitly inherit from RendererABC!
class RendererABC(ABC):
  @abstractmethod
  def render(self) -> str:
    pass

def draw(item: RendererABC):
  print(item.render())

class ThirdPartyWidget: # Does NOT inherit from RendererABC
  def render(self) -> str:
    return '<div>Widget</div>'

