from typing import Protocol

# ✅ NEW: Protocol allows any class with a matching render() signature
# to pass static type checking without explicit inheritance!
class Renderable(Protocol):
  def render(self) -> str: ...

def draw(item: Renderable):
  print(item.render())

class ThirdPartyWidget:
  def render(self) -> str:
    return '<div>Widget</div>'

# ✅ Mypy / Pyright passes with 0 errors!
draw(ThirdPartyWidget())
